export type ParsedSubscribeInstruction<
  TProgram extends string = typeof SUBSCRIPTIONS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The subscriber creating the subscription (pays rent) */
    subscriber: TAccountMetas[0];
    /** The merchant who owns the plan */
    merchant: TAccountMetas[1];
    /** The plan PDA to subscribe to */
    planPda: TAccountMetas[2];
    /** The subscription PDA being created */
    subscriptionPda: TAccountMetas[3];
    /** The subscriber's SubscriptionAuthority PDA for the plan's mint */
    subscriptionAuthorityPda: TAccountMetas[4];
    /** The system program */
    systemProgram: TAccountMetas[5];
    /** The event authority PDA */
    eventAuthority: TAccountMetas[6];
    /** This program (for self-CPI) */
    selfProgram: TAccountMetas[7];
    /** Optional sponsor that funds the account rent. Defaults to the subscriber/signer when omitted. */
    payer?: TAccountMetas[8] | undefined;
  };
  data: SubscribeInstructionData;
};

export function parseSubscribeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSubscribeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 8) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 8,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  let optionalAccountsRemaining = instruction.accounts.length - 8;
  const getNextOptionalAccount = () => {
    if (optionalAccountsRemaining === 0) return undefined;
    optionalAccountsRemaining -= 1;
    return getNextAccount();
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      subscriber: getNextAccount(),
      merchant: getNextAccount(),
      planPda: getNextAccount(),
      subscriptionPda: getNextAccount(),
      subscriptionAuthorityPda: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      selfProgram: getNextAccount(),
      payer: getNextOptionalAccount(),
    },
    data: getSubscribeInstructionDataDecoder().decode(instruction.data),
  };
}
